#!/usr/bin/env python3
# PlovCoin site audit patch 2: OG v2 (embedded), inherited social metadata,
# Terms/Privacy SEO alternates, JSON-LD (Organization/WebSite/FAQPage), sitemap regen.
# Run from repo root: python apply_site_audit_2.py
import os, re, json, base64, datetime

done = []
def rd(p): return open(p, encoding="utf-8").read()
def wr(p, s):
    os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
    open(p, "w", encoding="utf-8").write(s)

# ---------- 1. OG IMAGE v2 (embedded, no manual step) ----------
PNG_B64 = ""
png = base64.b64decode(PNG_B64)
open("public/og-image-v2.png", "wb").write(png)
done.append("public/og-image-v2.png written (%d bytes)" % len(png))
for p in ("app/page.tsx", "app/ru/page.tsx"):
    s = rd(p)
    if "/og-image.png" in s:
        wr(p, s.replace("/og-image.png", "/og-image-v2.png")); done.append(p + ": og-image -> v2")

# ---------- 2. ROOT LAYOUT: inherited metadata (og/twitter) + JSON-LD ----------
p = "app/layout.tsx"; s = rd(p)
if "openGraph" not in s:
    s = s.replace('import type { Viewport } from "next";', 'import type { Metadata, Viewport } from "next";')
    meta = '''
export const metadata: Metadata = {
  metadataBase: new URL("https://plovcoin.com"),
  title: { default: "PlovCoin ($PLOV)", template: "%s" },
  description: "The first universal cultural memecoin on Solana. Fair launch, 45% to community, no presale, no VC.",
  openGraph: {
    type: "website",
    siteName: "PlovCoin",
    images: [{ url: "/og-image-v2.png", width: 1200, height: 630, alt: "PlovCoin ($PLOV)" }],
  },
  twitter: {
    card: "summary_large_image",
    site: "@PlovTeam",
    images: ["/og-image-v2.png"],
  },
};
'''
    s = s.replace('export const viewport: Viewport = {', meta + '\nexport const viewport: Viewport = {')
    jsonld = '''        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify([
            { "@context": "https://schema.org", "@type": "Organization", "name": "PlovCoin",
              "url": "https://plovcoin.com", "logo": "https://plovcoin.com/plov-logo.png",
              "sameAs": ["https://x.com/PlovTeam", "https://t.me/PlovCoinAnnouncements"] },
            { "@context": "https://schema.org", "@type": "WebSite", "name": "PlovCoin",
              "url": "https://plovcoin.com", "inLanguage": ["en", "ru"] }
          ]) }}
        />
'''
    s = s.replace('        <link rel="preconnect" href="https://fonts.googleapis.com" />',
                  jsonld + '        <link rel="preconnect" href="https://fonts.googleapis.com" />')
    wr(p, s); done.append("app/layout.tsx: inherited og/twitter metadata + Organization/WebSite JSON-LD")

# ---------- 3. TERMS / PRIVACY: canonical + hreflang ----------
def add_alt(path_, en_url, ru_url, is_ru):
    s = rd(path_)
    if "alternates" in s: return
    canon = ru_url if is_ru else en_url
    s = s.replace('export const metadata = { title:',
        'export const metadata = { alternates: { canonical: "%s", languages: { en: "%s", ru: "%s", "x-default": "%s" } }, title:' % (canon, en_url, ru_url, en_url))
    wr(path_, s); done.append(path_ + ": canonical/hreflang added")
add_alt("app/terms/page.tsx", "https://plovcoin.com/terms", "https://plovcoin.com/ru/terms", False)
add_alt("app/ru/terms/page.tsx", "https://plovcoin.com/terms", "https://plovcoin.com/ru/terms", True)
add_alt("app/privacy/page.tsx", "https://plovcoin.com/privacy", "https://plovcoin.com/ru/privacy", False)
add_alt("app/ru/privacy/page.tsx", "https://plovcoin.com/privacy", "https://plovcoin.com/ru/privacy", True)

# ---------- 4. FAQPage JSON-LD on FAQ pages ----------
def faq_jsonld(loc):
    d = json.load(open("lib/dictionaries/%s.json" % loc, encoding="utf-8"))
    items = d.get("faq", {}).get("featured", [])
    ents = [{"@type": "Question", "name": it["q"],
             "acceptedAnswer": {"@type": "Answer", "text": re.sub(r"<[^>]+>", "", it["a"])}} for it in items if "q" in it and "a" in it]
    return json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": ents}, ensure_ascii=False)
for loc, path_ in (("en", "app/faq/page.tsx"), ("ru", "app/ru/faq/page.tsx")):
    if not os.path.exists(path_): continue
    s = rd(path_)
    if "FAQPage" in s: continue
    ld = faq_jsonld(loc).replace("</", "<\\/")
    inject = '      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: %s }} />\n' % json.dumps(ld)
    s2 = re.sub(r'(return \(\s*\n\s*<I18nProvider[^>]*>\n)', lambda m: m.group(1) + inject, s, count=1)
    if s2 != s:
        wr(path_, s2); done.append(path_ + ": FAQPage JSON-LD (%s)" % loc)
    else:
        done.append(path_ + ": FAQ JSON-LD PATTERN NOT FOUND (skip)")

# ---------- 5. SITEMAP regen ----------
today = datetime.date.today().isoformat()
paths = ["", "/proof", "/whitepaper", "/plovdrop", "/faq", "/terms", "/privacy"]
sm = ['<?xml version="1.0" encoding="UTF-8"?>',
      '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">']
n = 0
for pth in paths:
    en = "https://plovcoin.com" + pth; ru = "https://plovcoin.com/ru" + pth
    for u in (en, ru):
        n += 1
        sm.append("  <url><loc>%s</loc><lastmod>%s</lastmod>"
                  '<xhtml:link rel="alternate" hreflang="en" href="%s"/>'
                  '<xhtml:link rel="alternate" hreflang="ru" href="%s"/>'
                  '<xhtml:link rel="alternate" hreflang="x-default" href="%s"/></url>' % (u, today, en, ru, en))
sm.append("</urlset>")
wr("public/sitemap.xml", "\n".join(sm) + "\n")
done.append("public/sitemap.xml regenerated: %d URLs, lastmod %s, hreflang" % (n, today))

print("=== PATCH 2 APPLIED ===")
for d_ in done: print(" -", d_)
print()
print("NEXT: python apply_full_site_audit.py --check ; npm run build ; git add -A ; git commit ; git push")
print("THEN (your side): Vercel redirect ru.plovcoin.com -> /ru ; Google Search Console re-index /, /whitepaper, /proof, /faq")
